#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

#include <cstddef>
#include <optional>
#include <stdexcept>
#include <vector>

namespace py = pybind11;

double media(const std::vector<double>& valores) {
    if (valores.empty()) throw std::invalid_argument("media espera al menos un valor");
    double suma = 0.0;
    for (double v : valores) suma += v;
    return suma / static_cast<double>(valores.size());
}

std::optional<std::size_t> indice_max(const std::vector<double>& valores) {
    if (valores.empty()) return std::nullopt;
    std::size_t mejor = 0;
    for (std::size_t i = 1; i < valores.size(); ++i) {
        if (valores[i] > valores[mejor]) mejor = i;
    }
    return mejor;
}

PYBIND11_MODULE(estadisticas, m) {
    m.def("media", &media, py::arg("valores"), "Media aritmetica de una lista");
    m.def("indice_max", &indice_max, py::arg("valores"),
          "Indice del mayor valor, o None si la lista esta vacia");
}

