#include <deque>
#include <stdexcept>
#include <vector>

namespace py = pybind11;

// Acepta cualquier array convertible a double contiguo (C-order).
double mean(py::array_t<double, py::array::c_style | py::array::forcecast> valores) {
    auto info = valores.request();
    if (info.ndim != 1) throw std::invalid_argument("mean espera un array 1-D");
    const auto n = static_cast<std::size_t>(info.shape[0]);
    if (n == 0) throw std::invalid_argument("mean espera al menos un valor");
    const auto* datos = static_cast<const double*>(info.ptr);
    double suma = 0.0;
    for (std::size_t i = 0; i < n; ++i) suma += datos[i];
    return suma / static_cast<double>(n);
}

std::vector<double> normalizar(const std::vector<double>& valores) {
    double maximo = 0.0;
    for (double v : valores) maximo = std::max(maximo, std::abs(v));
    if (maximo == 0.0) return std::vector<double>(valores.size(), 0.0);
    std::vector<double> salida;
    salida.reserve(valores.size());
    for (double v : valores) salida.push_back(v / maximo);
    return salida;
}

// Trabajo puro de C++: puede soltar el GIL durante el bucle.
long long sumar_hasta(long long n) {
    long long total = 0;
    for (long long i = 1; i <= n; ++i) total += i;
    return total;
}

class MediaMovil {
public:
    explicit MediaMovil(std::size_t ventana) : ventana_(ventana) {
        if (ventana == 0) throw std::invalid_argument("la ventana debe ser mayor que cero");
    }

    double push(double valor) {
        buffer_.push_back(valor);
        suma_ += valor;
        if (buffer_.size() > ventana_) {
            suma_ -= buffer_.front();
            buffer_.pop_front();
        }
        return suma_ / static_cast<double>(buffer_.size());
    }

    std::size_t size() const noexcept { return buffer_.size(); }

private:
    std::size_t ventana_;
    std::deque<double> buffer_;
    double suma_ = 0.0;
};

PYBIND11_MODULE(faststats, m) {
    m.doc() = "Estadisticas basicas implementadas en C++";

    m.def("mean", &mean, py::arg("valores"), "Media aritmetica de un array 1-D");
    m.def("normalizar", &normalizar, py::arg("valores"),
          "Divide cada valor por el maximo absoluto");
    m.def("sumar_hasta", &sumar_hasta, py::arg("n"),
          py::call_guard<py::gil_scoped_release>(),
          "Suma 1..n liberando el GIL mientras trabaja");

    py::class_<MediaMovil>(m, "MediaMovil")
        .def(py::init<std::size_t>(), py::arg("ventana"))
        .def("push", &MediaMovil::push, py::arg("valor"),
             "Anade un valor y devuelve la media de la ventana")
        .def_property_readonly("size", &MediaMovil::size)
        .def("__repr__", [](const MediaMovil& mm) {
            return "<MediaMovil size=" + std::to_string(mm.size()) + ">";
        });
}

