#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

#include <cstddef>
#include <stdexcept>
#include <vector>

namespace py = pybind11;

double producto_punto(const std::vector<double>& a, const std::vector<double>& b) {
    if (a.size() != b.size()) {
        throw std::invalid_argument("los vectores deben tener el mismo tamano");
    }
    double total = 0.0;
    for (std::size_t i = 0; i < a.size(); ++i) total += a[i] * b[i];
    return total;
}

PYBIND11_MODULE(vector_ops, m) {
    m.def("producto_punto", &producto_punto, py::arg("a"), py::arg("b"),
          "Producto escalar de dos vectores");
}

#include <pybind11/pybind11.h>

#include <string>

namespace py = pybind11;

class Contador {
public:
    void incrementar() { ++valor_; }
    void reiniciar() { valor_ = 0; }
    int valor() const { return valor_; }

private:
    int valor_ = 0;
};

PYBIND11_MODULE(contador, m) {
    py::class_<Contador>(m, "Contador")
        .def(py::init<>())
        .def("incrementar", &Contador::incrementar)
        .def("reiniciar", &Contador::reiniciar)
        .def_property_readonly("valor", &Contador::valor)
        .def("__repr__", [](const Contador& c) {
            return "<Contador valor=" + std::to_string(c.valor()) + ">";
        });
}

